head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "JLDFIL52600";
scwin.form = null;

// TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — isOk, loadTp

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_rowCopy();
        await scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldfil52600.onpageload' });
    }
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {void}
 * @hidden N
 */
scwin.init_rowCopy = function () {
    const rows = [{ childId: "__rb0", fn: function () { return "전체 " + String((dma_pageContext.get("totalCountIntValue") ?? "")) + "건 [" + String((dma_pageContext.get("currentPage") ?? "")) + "/" + String((dma_pageContext.get("totalPageCount") ?? "")) + "Page]"; } }];
    rows.forEach(function (it) {
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { return; }  // as-is 가 서버 렌더로 그리던 반복 행 — 산출에 없는 칸은 건너뛴다
        let v;
        try { v = it.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); return; }
        if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); }
    });
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_pageBody = async function () {
    try {
        scwin.form = (document.prelistPageForm || { elements: [] });
        await scwin.defaultCheck();

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil52600.onpageload' }); }
};

// [A] 초기 목록 미해결 — 같은 액션인데 method 가 2개다(grwthwrtrpt#getgrwthwrtrptlist vs grwthwrtrpt#submitgrwthwrtrpt) — 어느 것이 «열자마자» 인지 정할 근거가 없다

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name grd_pageResult_oncellclick
 * @description grd_pageResult 셀 클릭 이벤트
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 컬럼 id
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_pageResult_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_pageResult');
        if (!dl) { /* TODO Stage2: [sdd] 행 동작 대상 목록 없음: dlt_pageResult */ return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; }
        if (columnId === "__rowAct") { if (r["listProcsStatCd"] === '33'|| r["listProcsStatCd"] === '36') { await scwin.openAdjReqPopNw(r["bzProcsNo"], "180", "76"); return; } if (r["listProcsStatCd"] === '30' || r["listProcsStatCd"] === '35' || r["listProcsStatCd"] === '37') { await scwin.submitRpt(r["bzProcsNo"], "76"); return; } return; } if (r["listProcsStatCd"] !== '30' && r["listProcsStatCd"] !== '37' && r["listProcsStatCd"] !== '35') { await scwin.viewDetail(r["bzProcsNo"], r["seq"]); return; }
        if (r["listProcsStatCd"] === '30') { await scwin.viewDetail(r["bzProcsNo"], r["seq"]); return; }
        if (r["listProcsStatCd"] === '35') { await scwin.viewDetail(r["bzProcsNo"], r["seq"]); return; }
        if (r["listProcsStatCd"] === '37') { await scwin.viewDetail(r["bzProcsNo"], r["seq"]); return; }
        await scwin.viewDetail(r["bzProcsNo"], r["seq"]); return;
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_pageResult.oncellclick' });
    }
};

/**
 * @method
 * @name btn_newWrite_onclick
 * @description 「신규작성」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_newWrite_onclick = function(e){
    try {
        scwin.newWrite()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil52600.btn_newWrite_onclick' }); }
};

/**
 * @method
 * @name krxpage_pagenavigator_59_onclick
 * @description krxpage_pagenavigator_59 클릭 이벤트
 * @param {Number} index index
 * @returns {void}
 * @hidden N
 */
scwin.krxpage_pagenavigator_59_onclick = async function (index) {
    try {
        const pi = (index && typeof index === 'object') ? index.newSelectedIndex : index;
        $c.util.getComponent('dma_viewDetailReq').set('pageIndex', pi);
        await scwin.fncSearch();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "jldfil52600.krxpage_pagenavigator_59_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_viewDetail
 * @description view Detail 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_viewDetail = async function () {
    const sbmOptions = {
        id: "tx_viewDetail",
        method: "post",
        action: "/listInvstg/grwthWrtrpt.do",
        ref: "dma_viewDetailReq",
        target: "dlt_pageResult=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fncSearch
 * @description fnc Search 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fncSearch = async function () {
    const sbmOptions = {
        id: "tx_fncSearch",
        method: "post",
        action: "/listInvstg/grwthWrtrpt.do?method=getGrwthWrtrptList",
        ref: "dma_fncSearchReq",
        target: "dlt_pageResult=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_submitRpt
 * @description submit Rpt 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_submitRpt = async function () {
    const sbmOptions = {
        id: "tx_submitRpt",
        method: "post",
        action: "/listInvstg/grwthWrtrpt.do?method=submitGrwthWrtrpt",
        ref: "dma_submitRptReq",
        target: "dlt_pageResult=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name grd_pageResult_fillAct
 * @description grd page Result fill Act 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_pageResult_fillAct = async function () {
    try {
        const dl = $c.util.getComponent('dlt_pageResult');
        if (!dl || !dl.getTotalRow) { return; }
        for (let i = 0; i < dl.getRowCount(); i++) {
            const r = dl.getRowJSON(i);
            let v = '-';
            if (r) { if (r["listProcsStatCd"] === '33'|| r["listProcsStatCd"] === '36') { v = "수정요청"; } else if (r["listProcsStatCd"] === '30' || r["listProcsStatCd"] === '35' || r["listProcsStatCd"] === '37') { v = "제출"; } }
            dl.setCellData(i, "__rowAct", v);
        }
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_pageResult.fillAct' });
    }
};

/**
 * @method
 * @name viewDetail
 * @description view Detail 처리
 * @param {*} bzProcsNo bzProcsNo
 * @param {*} seq seq
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.viewDetail = async function (bzProcsNo, seq) {
    $c.util.getComponent('dma_viewDetailReq').set('bzProcsNo', bzProcsNo);
    $c.util.getComponent('dma_viewDetailReq').set('seq', seq);
    scwin.form.action = '/listInvstg/grwthWrtrpt.do';
    $c.util.getComponent('dma_viewDetailReq').set('method', 'editGrwthWrtrptForm');
    await scwin.tx_viewDetail();
};

/**
 * @method
 * @name newWrite
 * @description new Write 처리
 * @returns {void}
 * @hidden N
 */
scwin.newWrite = function () {
    $c.win.setPageFrameSrc($c.win.getFrame(), '/ui/jsp/JLDFIL52610.xml');
};

/**
 * @method
 * @name defaultCheck
 * @description default Check 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.defaultCheck = async function () {
    const isOk = (String(((dma_pageContext.get("isOk") ?? "")) == null ? '' : ((dma_pageContext.get("isOk") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("isOk") ?? "")) == null ? '' : ((dma_pageContext.get("isOk") ?? ""))));
    const loadTp = (String(((dma_pageContext.get("loadTp") ?? "")) == null ? '' : ((dma_pageContext.get("loadTp") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("loadTp") ?? "")) == null ? '' : ((dma_pageContext.get("loadTp") ?? ""))));
    if (loadTp === '4') {
        if (isOk) {
            await $c.win.alert('삭제되었습니다.');
        } else {
            await $c.win.alert('삭제시 오류가 발생 되었습니다.');
        }
    } else {
        if (isOk !== '') {
            if (isOk) {
                await $c.win.alert('제출되었습니다');
            } else {
                await $c.win.alert('제출시 오류가 발생했습니다.');
            }
            await $c.win.alert('화면 이동 미완 — 목적지 미확인(as-is: /jldfil52610/jldfil52610.xml?method=getGrwthWrtrptList&pageIndex=). 전환 대상 화면이 확정되면 연결됩니다.') + null;
        }
    }
};

/**
 * @method
 * @name fncSearch
 * @description fnc Search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fncSearch = async function () {
    const pageIndex = $c.util.getComponent('dma_viewDetailReq').get('pageIndex');
    $c.util.getComponent('dma_viewDetailReq').set('pageIndex', pageIndex);
    scwin.form.action = '/listInvstg/grwthWrtrpt.do?method=getGrwthWrtrptList';
    await scwin.tx_fncSearch();
};

/**
 * @method
 * @name submitRpt
 * @description submit Rpt 처리
 * @param {*} bzProcsNo bzProcsNo
 * @param {String} listBzDtlTpCd listBzDtlTpCd
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.submitRpt = async function (bzProcsNo, listBzDtlTpCd) {
    scwin.form.action = "/listInvstg/grwthWrtrpt.do?method=submitGrwthWrtrpt";
    $c.util.getComponent('dma_viewDetailReq').set('bzProcsNo', bzProcsNo);
    $c.util.getComponent('dma_viewDetailReq').set('listBzDtlTpCd', listBzDtlTpCd);
    if (await $c.win.confirm('제출하시겠습니까?')) {
        await scwin.tx_submitRpt();
    }
};

/**
 * @method
 * @name openAdjReqPopNw
 * @description open Adj Req Pop Nw 처리
 * @param {*} bzProcsNo bzProcsNo
 * @param {String} listInvstgBzTpCd listInvstgBzTpCd
 * @param {String} listBzDtlTpCd listBzDtlTpCd
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.openAdjReqPopNw = async function (bzProcsNo, listInvstgBzTpCd, listBzDtlTpCd) {
    w = '500';
    h = '250';
    l = screen.width / 2 - w / 2;
    t = screen.height / 2 - h / 2;
    const corpSearchURL = '/ui/jsp/JLDFIL52610.xml';
    await $c.win.openPopup(corpSearchURL, { id: "popup4adjReq", scrollbars: false, resizable: false, width: "500", height: "250", type: "pageFramePopup" }, { method: "selectAvailableAdjReq", bzProcsNo: bzProcsNo, listInvstgBzTpCd: listInvstgBzTpCd, listBzDtlTpCd: listBzDtlTpCd });
};
